using System;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "ChooseDiceStateMouseAction", menuName = "Data/Battle/Actions/ChooseDiceStateMouseAction")]
public class ChooseDiceStateMouseAction : Action
{
	[Header("Action Instance Reference")]
	[SerializeField]
	private ActionInstanceReference actionInstanceReference;

	private System.Action noValidRaycastMouseInputAction => delegate
	{
		if (base.actionInstance != null)
		{
			base.actionInstance.StopFollowingMouse();
			Debug.Log("NOT A DICE CAST TARGET SPACE");
		}
		else
		{
			Debug.Log("No UI Object");
		}
	};

	public override void Execute(float d)
	{
		base.inputManager.MouseInput(delegate(GameObject gameObject)
		{
			if (base.actionInstance == null)
			{
				ActionInstance componentInParent = gameObject.GetComponentInParent<ActionInstance>();
				if (componentInParent != null && actionInstanceReference.Value != componentInParent)
				{
					componentInParent.StartFollowingMouse();
				}
			}
			else
			{
				DiceTargetCastSpaceInstance componentInParent2 = gameObject.GetComponentInParent<DiceTargetCastSpaceInstance>();
				if (componentInParent2 != null && base.actionInstance != null)
				{
					DiceInstance diceInstance = base.actionInstance as DiceInstance;
					if (diceInstance.DiceState != DiceState.ReturningToHandAfterDrag && diceInstance.DiceState != DiceState.OnHand)
					{
						diceInstance.SetupDiceToStartFollowingMouse();
						componentInParent2.ActionDrop(base.actionInstance as DiceInstance);
						ReferenceSingleton<BattleHandler>.Instance.SetCurrentActionInstance(null);
					}
				}
				else
				{
					base.actionInstance.StopFollowingMouse();
					Debug.Log("NOT A DICE CAST TARGET SPACE");
				}
			}
		}, noValidRaycastMouseInputAction);
	}
}
